import 'package:flutter/material.dart';
import '../../../../data/mock/mock_data.dart';
class MajorsScreen extends StatefulWidget { const MajorsScreen({super.key}); @override State<MajorsScreen> createState() => _MajorsScreenState(); }
class _MajorsScreenState extends State<MajorsScreen> { String query = ''; @override Widget build(BuildContext context) { final items = MockData.majors.where((major) => major.name.contains(query) || major.category.contains(query)).toList(); return Scaffold(appBar: AppBar(title: const Text('دليل التخصصات')), body: ListView(padding: const EdgeInsets.all(20), children: <Widget>[TextField(onChanged: (String value) => setState(() => query = value), decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'ابحث عن تخصص')), const SizedBox(height:12), ...items.map((major) => Card(child: ListTile(onTap: () => Navigator.pushNamed(context, '/major-details', arguments: major), title: Text(major.name), subtitle: Text(major.description), trailing: const Icon(Icons.chevron_left))))])); } }
